from fastapi.responses import HTMLResponse


def evidence_library_page():
    return HTMLResponse(r'''<!doctype html>
<html class="nct-shell-loading" lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Evidence Library</title><style id="nct-shell-bootstrap">html.nct-shell-loading body{visibility:hidden}</style>
<style>
:root{color-scheme:dark;--bg:#09131c;--panel:#112330;--line:#304955;--text:#e8f2f6;--muted:#abc0cb;--accent:#62d9ba}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui}body>header{padding:20px 4vw;border-bottom:1px solid var(--line)}main{max-width:1700px;margin:auto;padding:28px 3vw 60px}h1{margin:6px 0 12px}h2{font-size:18px}.hint{color:var(--muted)}.panel{background:var(--panel);padding:20px;border:1px solid var(--line);border-radius:10px}.library-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:20px 0}.library-filters label{display:grid;gap:5px;font-size:13px}input,select,button,.button-link{font:inherit;background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:9px;min-height:40px}button,.button-link{cursor:pointer}button:disabled{opacity:.5;cursor:default}a{color:var(--accent)}.library-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.table-wrap{overflow-x:auto;overflow-y:visible}table{width:100%;min-width:1000px;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:12px 10px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{position:static;font-size:12px;text-transform:uppercase;color:var(--muted)}td{max-width:300px}td:nth-child(2){min-width:180px}.library-detail{padding:16px;max-width:100%;white-space:normal}.library-detail ul{display:flex;flex-wrap:wrap;gap:12px 24px;list-style:none;padding:0}.library-detail code{overflow-wrap:anywhere}.library-message{min-height:28px;margin:12px 0}.library-loading{height:4px;background:var(--accent);animation:pulse 1s infinite alternate} @keyframes pulse{to{opacity:.25}}[hidden]{display:none!important}@media(prefers-reduced-motion:reduce){.library-loading{animation:none}}@media(max-width:650px){main{padding:20px 12px}.panel{padding:12px}}
</style><script src="/assets/nct-session.js"></script></head><body>
<header><strong>NCT</strong> · Network Correlation &amp; Triage</header><main>
<p class="hint">Evidence</p><h1>Evidence Library</h1>
<p>Find active retained Nmap scans, imported XML, and device collection files together. Retired encounters stay in the audit record but no longer appear in this working catalog. Use the filters, then open a record’s files or analysis.</p>
<section class="panel" aria-label="Retained evidence catalog">
<form id="libraryFilters" class="library-filters" data-library-help="filters">
<label>Network, CIDR, device or filename<input id="librarySearch" type="search" maxlength="200" placeholder="Example: Office Servers or 10.2.0.0/24"></label>
<label>Evidence type<select id="libraryType"><option value="">All types</option><option value="scan">Nmap scan</option><option value="import">Imported Nmap XML</option><option value="device">Device collection / upload</option></select></label>
<label>Network Scope<select id="libraryScope"><option value="">All scopes</option><option value="__unknown__">Unknown / unassigned</option></select></label>
<label>Analyst<input id="libraryAnalyst" type="search" maxlength="100" placeholder="Recorded analyst name"></label>
<label>Saved from (UTC)<input id="libraryFrom" type="date"></label><label>Saved through (UTC)<input id="libraryThrough" type="date"></label>
<div class="library-actions"><button type="submit">Apply filters</button><button id="libraryReset" type="button">Clear filters</button></div></form>
<p class="hint" data-library-help="meaning">Each entry is a retained encounter, not a newly discovered host. The recorded state does not prove file integrity, current device health, or complete network coverage. Unknown means no usable value was recorded.</p>
<div id="libraryLoading" class="library-loading" role="progressbar" aria-label="Loading evidence" hidden></div>
<p id="libraryStatus" role="status" aria-live="polite" class="library-message">Loading retained evidence…</p>
<p id="libraryCoverage" class="hint" data-library-help="coverage"></p>
<div class="table-wrap" data-nct-table-mode="static"><table aria-label="Retained evidence"><thead><tr><th>Saved (UTC)</th><th>Type / evidence</th><th>Network / device</th><th>Network Scope</th><th>Analyst</th><th>Recorded state</th><th>Open</th></tr></thead><tbody id="libraryRows"></tbody></table></div>
<div class="library-actions" style="margin-top:16px" data-library-help="paging"><button id="libraryPrevious" type="button" disabled>Previous</button><button id="libraryNext" type="button" disabled>Next</button><span id="libraryPage"></span></div>
<p class="hint">Saved dates describe when NCT retained the record. They may differ from collection times inside the original evidence. Search matches literal recorded text; a CIDR search does not calculate subnet membership. Imported XML without recorded network metadata remains searchable by filename and source ID.</p>
</section></main><script>
(() => {'use strict';
const el=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cursor='',next='',stack=[],page=1,revision=0,records=[],busy=false;
const labels={scan:'Nmap scan',import:'Imported Nmap XML',device:'Device collection / upload'};
function controls(){el('libraryPrevious').disabled=busy||!stack.length;el('libraryNext').disabled=busy||!next;}
async function load(){const mine=++revision;busy=true;controls();el('libraryLoading').hidden=false;el('libraryRows').replaceChildren();el('libraryStatus').textContent='Loading retained evidence…';
const params=new URLSearchParams({q:el('librarySearch').value,kind:el('libraryType').value,scope:el('libraryScope').value,analyst:el('libraryAnalyst').value,start:el('libraryFrom').value,end:el('libraryThrough').value,limit:'25',after:cursor});
try{const response=await fetch('/api/evidence-library?'+params),data=await response.json();if(!response.ok)throw Error(data.detail||'Evidence could not be loaded');if(mine!==revision)return;
records=data.items;next=data.next_cursor||'';const selected=el('libraryScope').value;el('libraryScope').innerHTML='<option value="">All scopes</option><option value="__unknown__">Unknown / unassigned</option>'+(data.scopes||[]).map(s=>`<option value="${esc(s.id)}">${esc(s.label)}</option>`).join('');el('libraryScope').value=selected;
el('libraryCoverage').textContent=data.device_coverage;el('libraryStatus').textContent=`${data.total} matching retained encounter${data.total===1?'':'s'}. ${records.length} on this page.`;el('libraryPage').textContent=`Page ${page} · newest saved first`;
el('libraryRows').innerHTML=records.map((r,i)=>`<tr><td>${esc(r.saved_at)}</td><td>${esc(labels[r.kind])}<br><strong>${esc(r.title)}</strong></td><td>${esc(r.network)}</td><td>${esc(r.scope_name)}</td><td>${esc(r.actor)}</td><td>${esc(r.status)}</td><td><div class="library-actions"><button type="button" data-library-record="${i}" aria-expanded="false">Files and context</button>${r.analysis_url?`<a href="${esc(r.analysis_url)}">Open analysis</a>`:''}</div></td></tr><tr id="libraryDetail${i}" hidden><td colspan="7"><div class="library-detail" data-library-help="source"></div></td></tr>`).join('')||'<tr><td colspan="7">No records match these filters. Clear filters to see all retained evidence.</td></tr>';
}catch(error){if(mine===revision){next='';el('libraryStatus').textContent=error.message;el('libraryCoverage').textContent='No evidence was changed. Check System Health or try again.';}}finally{if(mine===revision){busy=false;el('libraryLoading').hidden=true;controls();}}}
el('libraryFilters').onsubmit=e=>{e.preventDefault();cursor='';stack=[];page=1;load();};
function filtersEdited(){revision++;cursor='';next='';stack=[];page=1;busy=false;records=[];el('libraryLoading').hidden=true;el('libraryRows').replaceChildren();el('libraryStatus').textContent='Filters changed. Select Apply filters to load matching evidence.';el('libraryPage').textContent='';controls();}
el('libraryFilters').addEventListener('input',filtersEdited);
el('libraryFilters').addEventListener('change',filtersEdited);
el('libraryReset').onclick=()=>{el('libraryFilters').reset();cursor='';stack=[];page=1;load();};
el('libraryNext').onclick=()=>{stack.push(cursor);cursor=next;page++;load();};el('libraryPrevious').onclick=()=>{cursor=stack.pop()||'';page=Math.max(1,page-1);load();};
el('libraryRows').onclick=async e=>{const button=e.target.closest('[data-library-record]');if(!button)return;const index=Number(button.dataset.libraryRecord),r=records[index],row=el('libraryDetail'+index),box=row.firstElementChild.firstElementChild;if(!row.hidden){row.hidden=true;button.setAttribute('aria-expanded','false');return;}row.hidden=false;button.setAttribute('aria-expanded','true');
box.innerHTML=`<p><strong>Retained encounter:</strong> <code>${esc(r.id)}</code></p><p>${r.kind==='import'?'Imports with identical bytes can appear more than once because each encounter has its own analyst, time and scope. The original download may use the first saved filename. Analysis remains in Import & Investigate so a shared-content result cannot be mistaken for this encounter’s scope.':'Files are opened through the existing source checks. Analysis opens the retained source; it does not start collection.'}</p><p class="library-file-status" role="status"></p><ul class="library-files"></ul>`;
const list=box.querySelector('ul'),status=box.querySelector('.library-file-status');if(r.download_url){const li=document.createElement('li'),a=document.createElement('a');a.href=r.download_url;a.textContent='Save original analysis-ready XML';li.append(a);list.append(li);}if(r.kind==='device'&&r.detail_url){status.textContent='Checking this collection’s retained files…';try{const response=await fetch(r.detail_url),data=await response.json();if(!response.ok)throw Error(data.detail||'Files unavailable');for(const f of data.artifacts||[]){if(typeof f.url!=='string'||!f.url.startsWith('/api/device-configs/'+encodeURIComponent(r.source_id)+'/files/'))continue;const li=document.createElement('li'),a=document.createElement('a');a.href=f.url;a.textContent=f.name;li.append(a);list.append(li);}const outputs=(data.artifacts||[]).filter(f=>f.name!=='manifest.json');status.textContent=outputs.length?'Select a file to save it. Follow your browser’s save prompt.':list.children.length?'Only the manifest is retained; no configuration or output file is available for this encounter.':'No retained files are currently available.';}catch(error){status.textContent=error.message;}}else if(!r.download_url){status.textContent='This source is unavailable or needs review. Refresh the library after resolving the recorded issue.';}};
load();})();
</script></body></html>''')
